/**
 * Generates placeholder tuyau registry files so the dashboard can build
 * without a running dev server. The dev server overwrites these with real
 * route types at runtime; for CI we only need the build to succeed.
 */
import { mkdirSync, writeFileSync, existsSync } from 'node:fs'
import { join } from 'node:path'

const dir = join('apps', 'core', '.adonisjs', 'client', 'registry')

// Skip if real registry already exists (e.g. already generated by dev server)
if (existsSync(join(dir, 'index.ts'))) {
  console.log('Tuyau registry already exists, skipping placeholder generation.')
  process.exit(0)
}

mkdirSync(dir, { recursive: true })

writeFileSync(
  join(dir, 'index.ts'),
  `/* eslint-disable prettier/prettier */
/* Placeholder – overwritten by the tuyau dev server with real route types. */
import type { AdonisEndpoint } from '@tuyau/core/types'
import type { Registry } from './schema.d.ts'
import type { ApiDefinition } from './tree.d.ts'

const placeholder: any = {}

const routes = {} as const satisfies Record<string, AdonisEndpoint>

export { routes }

export const registry = {
  routes,
  $tree: {} as ApiDefinition,
}

declare module '@tuyau/core/types' {
  export interface UserRegistry {
    routes: typeof routes
    $tree: ApiDefinition
  }
}
`
)

writeFileSync(
  join(dir, 'schema.d.ts'),
  `/* eslint-disable prettier/prettier */
/* Placeholder – overwritten by the tuyau dev server with real route types. */
import type { ExtractBody, ExtractErrorResponse, ExtractQuery, ExtractQueryForGet, ExtractResponse } from '@tuyau/core/types'
import type { InferInput, SimpleError } from '@vinejs/vine/types'

export type ParamValue = string | number | bigint | boolean

export interface Registry {}
`
)

writeFileSync(
  join(dir, 'tree.d.ts'),
  `/* eslint-disable prettier/prettier */
/* Placeholder – overwritten by the tuyau dev server with real route types. */
import type { routes } from './index.ts'

export interface ApiDefinition {}
`
)

console.log(`Tuyau registry placeholder created at ${dir}`)
